contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr, uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount <= address(this).balance);

        // Precondition: we call SetLogFile before initialization.
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;

        // Check that SetLogFile was accepted and then Initialized succeeds before any Put can happen.
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { initReverted = true; } else { initReverted = false; }

        assert(!initReverted);
    }

    receive() external payable {}
}

